const PRECACHE_PATHS = new Set(PRECACHE_URLS);
const NETWORK_FIRST_PATHS = new Set([
  "/ucsbxrp/offline-manifest.json",
  SCOPE_PATH + "course/current/release.json",
]);
const CLIENT_STATE_CACHE = CACHE_PREFIX + "clients";

function isShellCache(name) {
  return name.startsWith(CACHE_PREFIX) && /^[a-f0-9]{20}$/.test(name.slice(CACHE_PREFIX.length));
}

function clientRecordUrl(id) {
  return new URL(SCOPE_PATH + "__shell_clients/" + encodeURIComponent(id), self.location.origin).href;
}

async function cleanUnusedShells() {
  const clients = (await self.clients.matchAll({ type: "window", includeUncontrolled: true }))
    .filter((client) => new URL(client.url).pathname.startsWith(SCOPE_PATH));
  const records = await caches.open(CLIENT_STATE_CACHE);
  const liveUrls = new Set(clients.map((client) => clientRecordUrl(client.id)));
  for (const key of await records.keys()) {
    if (!liveUrls.has(key.url)) await records.delete(key);
  }
  const retained = new Set([CACHE_NAME]);
  let unknownClient = false;
  for (const client of clients) {
    const record = await records.match(clientRecordUrl(client.id));
    if (!record) {
      unknownClient = true;
      client.postMessage({ type: "ucsb-xrp-shell-identify" });
      continue;
    }
    const name = await record.text();
    if (isShellCache(name)) retained.add(name);
    else unknownClient = true;
  }
  // A suspended/older client cannot answer an identification request yet.
  // Keep its assets until it responds or disappears from the browser's list.
  if (unknownClient) return;
  const names = (await caches.keys()).filter(isShellCache);
  const previous = names.filter((name) => name !== CACHE_NAME).at(-1);
  if (previous) retained.add(previous);
  await Promise.all(names.filter((name) => !retained.has(name)).map((name) => caches.delete(name)));
}

self.addEventListener("message", (event) => {
  if (event.data?.type !== "ucsb-xrp-shell-client" || !event.source?.id) return;
  const name = event.data.cacheName;
  if (typeof name !== "string" || !isShellCache(name)) return;
  event.waitUntil((async () => {
    const records = await caches.open(CLIENT_STATE_CACHE);
    await records.put(clientRecordUrl(event.source.id), new Response(name));
    await cleanUnusedShells();
  })());
});

function withIsolationHeaders(response) {
  const headers = new Headers(response.headers);
  headers.set("Cross-Origin-Opener-Policy", "same-origin");
  headers.set("Cross-Origin-Embedder-Policy", "require-corp");
  headers.set("Cross-Origin-Resource-Policy", "same-origin");
  return new Response(response.body, {
    status: response.status,
    statusText: response.statusText,
    headers,
  });
}

function navigationFallback(pathname) {
  if (!pathname.startsWith(SCOPE_PATH)) {
    return null;
  }

  const relativePath = pathname.slice(SCOPE_PATH.length).replace(/^\/+|\/+$/g, "");
  if (relativePath === "" || relativePath === "index.html") {
    return SCOPE_PATH + "index.html";
  }

  for (const application of [
    "ide",
    "monitor",
    "workspace",
    "dashboard",
    "guide",
    "reference",
    "commission",
    "author",
    "instructor",
    "overview",
  ]) {
    if (relativePath === application || relativePath === application + "/index.html") {
      return SCOPE_PATH + application + "/index.html";
    }
  }

  // Published reading pages and direct downloads are cached documents too.
  // Only manifest entries qualify; unknown URLs still use ordinary networking.
  const publishedFile = SCOPE_PATH + relativePath;
  if (PRECACHE_PATHS.has(publishedFile)) return publishedFile;
  if (PRECACHE_PATHS.has(publishedFile + "/index.html")) return publishedFile + "/index.html";
  return null;
}

self.addEventListener("install", (event) => {
  event.waitUntil((async () => {
    const cacheAlreadyExisted = await caches.has(CACHE_NAME);
    const controller = new AbortController();
    const timeout = setTimeout(() => controller.abort(), 90_000);
    try {
      const cache = await caches.open(CACHE_NAME);
      const requests = PRECACHE_URLS.map(
        (url) => new Request(url, { cache: "reload", credentials: "same-origin", signal: controller.signal }),
      );
      await cache.addAll(requests);
      await self.skipWaiting();
    } catch (error) {
      // addAll commits atomically. A failed forced refresh must preserve the
      // installed copy of this same release for offline use.
      if (!cacheAlreadyExisted) await caches.delete(CACHE_NAME);
      throw error;
    } finally {
      clearTimeout(timeout);
    }
  })());
});

self.addEventListener("activate", (event) => {
  event.waitUntil((async () => {
    await self.clients.claim();
    await cleanUnusedShells();
  })());
});

self.addEventListener("fetch", (event) => {
  const request = event.request;
  if (request.method !== "GET") {
    return;
  }

  const url = new URL(request.url);
  if (url.origin !== self.location.origin) {
    return;
  }

  // Keep repair independent from the app cache, including future repair updates.
  if (url.pathname === SCOPE_PATH + "refresh.html" || url.pathname === SCOPE_PATH + "refresh-manifest.json") {
    event.respondWith(fetch(new Request(request, { cache: "no-store" })));
    return;
  }
  if (request.mode === "navigate" && url.searchParams.get("refresh") === "1" && url.pathname.startsWith(SCOPE_PATH)) {
    event.respondWith(Response.redirect(new URL(SCOPE_PATH + "refresh.html", self.location.origin).href, 302));
    return;
  }

  if (request.mode === "navigate") {
    const fallbackUrl = navigationFallback(url.pathname);
    if (fallbackUrl !== null) {
      event.respondWith((async () => {
        const cache = await caches.open(CACHE_NAME);
        const cached = await cache.match(
          new URL(fallbackUrl, self.location.origin).toString(),
        );
        if (cached !== undefined) {
          return withIsolationHeaders(cached);
        }
        return withIsolationHeaders(await fetch(request));
      })());
    }
    return;
  }

  const canonicalUrl = url.pathname;
  if (NETWORK_FIRST_PATHS.has(canonicalUrl)) {
    event.respondWith((async () => {
      const controller = new AbortController();
      const timeout = setTimeout(() => controller.abort(), 2_500);
      try {
        const response = await fetch(
          new Request(request, { cache: "no-store", signal: controller.signal }),
        );
        if (!response.ok) throw new Error("Release information is unavailable online");
        const body = await response.arrayBuffer();
        return withIsolationHeaders(new Response(body, {
          status: response.status, statusText: response.statusText, headers: response.headers,
        }));
      } catch {
        const cache = await caches.open(CACHE_NAME);
        const response = await cache.match(url.toString(), {
          ignoreSearch: true,
        });
        if (response === undefined) {
          throw new Error("Offline release information is unavailable");
        }
        return withIsolationHeaders(response);
      } finally {
        clearTimeout(timeout);
      }
    })());
    return;
  }
  if (PRECACHE_PATHS.has(canonicalUrl)) {
    event.respondWith(
      caches
        .open(CACHE_NAME)
        .then((cache) => cache.match(url.toString(), { ignoreSearch: true }))
        .then((cached) => cached ?? fetch(request))
        .then(withIsolationHeaders),
    );
    return;
  }

  const isVersionedAsset =
    canonicalUrl.startsWith(SCOPE_PATH + "assets/") ||
    // New builds use immutable release-scoped commissioning paths. Retaining
    // the broader prefix lets the first scoped release serve an already-open
    // legacy page from the immediately preceding cache, without publishing a
    // new mutable commissioning manifest.
    canonicalUrl.startsWith(SCOPE_PATH + "course/commissioning/") ||
    canonicalUrl.startsWith(SCOPE_PATH + "course/current/firmware/");
  if (!isVersionedAsset) {
    return;
  }

  event.respondWith(
    caches
      .match(url.toString(), { ignoreSearch: true })
      .then((cached) => cached ?? fetch(request))
      .then(withIsolationHeaders),
  );
});
